const body = $('Webhook').item.json.body || {};
const bike = body.motorcycle || ($('Get Motorcycle').first().json || {});
const rows = $input.all().map(i => i.json);
const productIds = body.productIds || [];

function brandMatches(a,b){a=(a||'').toLowerCase();b=(b||'').toLowerCase();if(!a||!b)return false;if(a==='universal')return true;return a===b||a.includes(b)||b.includes(a);}
function modelMatches(a,b){a=(a||'').toLowerCase();b=(b||'').toLowerCase();if(!a||!b)return false;if(a==='all models'||a==='universal')return true;return a===b||a.includes(b)||b.includes(a);}
function yearMatches(row,y){if(y==null)return true;y=Number(y);if(row.year_exact!=null)return Number(row.year_exact)===y;if(row.year_from!=null&&y<Number(row.year_from))return false;if(row.year_to!=null&&y>Number(row.year_to))return false;return true;}

const brand = bike.brand || bike.motorcycle_brand;
const model = bike.model || bike.motorcycle_model;
const year = bike.year || bike.motorcycle_year;
const items=[]; const errors=[];
for (const pid of productIds) {
  const hit = rows.find(r => r.product_id===pid && brandMatches(r.brand,brand) && modelMatches(r.model,model) && yearMatches(r,year));
  const compatible = !!hit;
  items.push({ productId: pid, compatible, reason: compatible ? null : 'This product is not marked as compatible with your selected motorcycle.' });
  if (!compatible) errors.push({ productId: pid, code: 'incompatible', message: 'This product is not marked as compatible with your selected motorcycle.' });
}
return [{ json: { compatible: errors.length===0, items, errors, motorcycle: { brand, model, year }, customerId: body.customerId } }];
